targets.expr:
((
  (sum(count_over_time(
  {service_name="gateway",deployment_environment_name="demo"} | json event="event", classification="classification", route="route" | __error__ = "" | event="gateway.request" | classification="success" | keep event, classification, route
  [5m]
))) or on() (0 * (sum(count_over_time(
  {service_name="gateway",deployment_environment_name="demo"} | json event="event", classification="classification", route="route" | __error__ = "" | event="gateway.request" | classification=~"success|service_failure" | keep event, classification, route
  [5m]
))))
) / ((sum(count_over_time(
  {service_name="gateway",deployment_environment_name="demo"} | json event="event", classification="classification", route="route" | __error__ = "" | event="gateway.request" | classification=~"success|service_failure" | keep event, classification, route
  [5m]
))) > 0))
  and on() (
    sum(count_over_time(
      {service_name="gateway",deployment_environment_name="demo"}
      | json event="event"
      | __error__ = ""
      | event="gateway.healthcheck"
      | keep event
      [1m]
    )) > 0
  )

((
  (sum(count_over_time(
  {service_name="gateway",deployment_environment_name="demo"} | json event="event", classification="classification", route="route", duration_seconds="duration_seconds" | __error__ = "" | event="gateway.request" | classification="success" | duration_seconds <= 0.500 | keep event, classification, route
  [5m]
))) or on() (0 * (sum(count_over_time(
  {service_name="gateway",deployment_environment_name="demo"} | json event="event", classification="classification", route="route" | __error__ = "" | event="gateway.request" | classification="success" | keep event, classification, route
  [5m]
))))
) / ((sum(count_over_time(
  {service_name="gateway",deployment_environment_name="demo"} | json event="event", classification="classification", route="route" | __error__ = "" | event="gateway.request" | classification="success" | keep event, classification, route
  [5m]
))) > 0))
  and on() (
    sum(count_over_time(
      {service_name="gateway",deployment_environment_name="demo"}
      | json event="event"
      | __error__ = ""
      | event="gateway.healthcheck"
      | keep event
      [1m]
    )) > 0
  )
